def count_numbers(a, b):
    count = 0
    for length in range(2, 61):
        for zero_pos in range(1, length):
            num = (1 << (length - 1)) | (1 << (length - 1 - zero_pos))
            if a <= num <= b:
                count += 1
    return count

a, b = map(int, input().split())
print(count_numbers(a, b))
