import sys

def count_numbers(a, b):
    count = 0
    for k in range(2, 62):
        for m in range(1, k):
            num = ((1 << k) - 1) - (1 << (k - 1 - m))
            if a <= num <= b:
                count += 1
    return count

a, b = map(int, sys.stdin.readline().split())
print(count_numbers(a, b))
```

